import {Sound} from './sound.js';
import {recipes,makeConfig,cupState} from './recipes.js';
import {scene} from './animation.js';
const $=id=>document.getElementById(id),KEY='little-moka-session-v3';let session=null,selected=recipes[0],view=0,animStart=performance.now(),lastFrame=0,lastDraw=-1;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const sound=new Sound();
function soundUI(){$('sound').textContent=sound.enabled?'♪ 音效开':'♪ 音效关';$('sound').setAttribute('aria-pressed',String(sound.enabled));$('sound').setAttribute('aria-label',sound.enabled?'关闭音效':'开启音效');}
soundUI();$('sound').onclick=()=>{sound.toggle();soundUI();};
document.addEventListener('pointerdown',()=>sound.unlock(),{passive:true});
document.addEventListener('keydown',()=>sound.unlock());
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.disabled&&!['sound','next','timerStart'].includes(b.id))sound.play('click');});
let feedbackTimeout;
function feedback(){clearTimeout(feedbackTimeout);$('stepFeedback').textContent='✓ 又完成一小步！';$('stepFeedback').classList.add('visible');feedbackTimeout=setTimeout(()=>$('stepFeedback').classList.remove('visible'),1200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(session));}catch{}}
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.schema===1&&raw.recipe?.steps?.length&&Number.isInteger(raw.frontier)&&raw.frontier>=0&&raw.frontier<raw.recipe.steps.length&&!raw.finished){makeConfig(raw.recipe,raw.config.target,raw.config.capacity,raw.config.dose,raw.config.preground);session=raw;}}catch{}
function show(id){window.scrollTo(0,0);['welcome','ritual','finish'].forEach(x=>$(x).hidden=x!==id);$('choose').hidden=id==='welcome';}
function fill(text){return text.replace(/\{(\w+)\}/g,(_,key)=>session.config[key]??'');}
$('recipeCards').innerHTML=recipes.map(r=>{const c=makeConfig(r);return `<button class="card ${r.color}" data-recipe="${r.id}">${scene({action:'pourMilk',add:'milk'},1,c,{coffee:r.method==='filter'?200:60,milk:0,ice:r.method==='iced'?70:0,filter:0})}<span class="tag">${r.tag}</span><h2>${r.name}</h2><p>${r.subtitle}</p><div class="card-bottom"><span>${r.steps.length} 个小步骤</span><span class="arrow">↗</span></div></button>`}).join('');
$('resume').hidden=!session;
$('recipeCards').onclick=e=>{const card=e.target.closest('[data-recipe]');if(!card)return;selected=recipes.find(r=>r.id===card.dataset.recipe);$('setupTitle').textContent=selected.name;$('equipment').textContent=selected.equipment;$('target').min=selected.range[0];$('target').max=selected.range[1];$('target').value=selected.base;$('doseField').hidden=selected.method==='filter';$('volumeHint').textContent=selected.method==='iced'?'含冰块占用空间的近似杯量。':selected.method==='filter'?'成品估算量；豆量与注水量按比例调整。':'咖啡入杯量固定 60ml，调整奶量；粉篮容量独立设置。';updateConfig();$('setup').showModal();};
function readConfig(){return makeConfig(selected,+$('target').value,+$('capacity').value,+$('dose').value,$('preground').checked);}
function updateConfig(){$('targetValue').textContent=$('target').value+' ml';try{const c=readConfig();$('summary').textContent=selected.method==='filter'?`${c.dose}g 咖啡粉 · ${c.water}g 冲煮水 · 成品约 ${c.target}ml`:`${c.dose}g 满篮粉 · 入杯咖啡 ${c.coffee}ml · 牛奶 ${c.milk}ml${c.ice?' · 冰块 '+c.ice+'g':''}`;$('error').textContent='';$('start').disabled=false;}catch(e){$('summary').textContent='调整杯量与杯子容量后开始。';$('error').textContent=e.message;$('start').disabled=true;}}
$('configForm').oninput=updateConfig;$('close').onclick=()=>$('setup').close();
$('configForm').onsubmit=e=>{e.preventDefault();let c;try{c=readConfig();}catch{return;}const recipe=structuredClone(selected);if(c.preground){recipe.steps[0]={...recipe.steps[0],action:'basket',title:'准备好咖啡粉',text:recipe.method==='filter'?'称取 {dose}g 中等研磨咖啡粉，准备 {water}g 冲煮用水。':'准备约 {dose}g 中细咖啡粉，以你的粉篮松散装满刮平为准。',tip:'使用适合当前冲煮方法的粗细。',produces:'grounds'};}
session={schema:1,recipe,config:c,frontier:0,timers:{},finished:false};view=0;save();$('setup').close();show('ritual');render();};
function render(){const s=session.recipe.steps[view];$('recipeName').textContent=session.recipe.name;$('stepCount').textContent=`${String(view+1).padStart(2,'0')} / ${String(session.recipe.steps.length).padStart(2,'0')}`;$('bar').style.width=((view+1)/session.recipe.steps.length*100)+'%';$('stepLabel').textContent=view<session.frontier?'已完成 · 回看一下':'这一步，跟着做';$('taskNumber').textContent=String(view+1).padStart(2,'0');$('stageCue').textContent=view<session.frontier?'可以重看，不用再做一遍':'小动画演示 · 你来实际操作';$('title').textContent=s.title;$('description').replaceChildren(...fill(s.text).split(/(\d+(?:[.–-]\d+)?\s*(?:ml|g|秒|°C))/g).map((part,i)=>{if(i%2){const el=document.createElement('strong');el.textContent=part;return el;}return document.createTextNode(part);}));$('tip').textContent=s.tip;$('scene').setAttribute('aria-label',s.title+'，'+fill(s.text));$('timer').hidden=!s.seconds;$('amounts').textContent=`目标约 ${session.config.target}ml · 杯子 ${session.config.capacity}ml${session.config.preground?' · 现成咖啡粉':''}`;$('back').disabled=view===0;$('reviewNote').textContent=view<session.frontier?'回看不会重复加料':'按自己的节奏';$('next').textContent=view<session.frontier?'回到当前步骤 →':view===session.recipe.steps.length-1?'做好了，完成这杯 ✓':'做好了，下一步 →';animStart=performance.now();lastDraw=-1;draw(reduced?1:0);updateTimer();if(view===session.frontier)sound.action(s.action);}
function remaining(){const s=session.recipe.steps[view],t=session.timers[view];if(!t)return s.seconds;return t.end?Math.max(0,Math.ceil((t.end-Date.now())/1000)):t.left;}
function updateTimer(){if(!session)return;const s=session.recipe.steps[view];if(!s.seconds){$('next').disabled=false;return;}const t=session.timers[view],left=remaining();$('clock').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('timerStatus').textContent=left===0?'时间到，可以继续了':t?.end?'正在计时，切换页面仍会继续':t?'已暂停':'实际操作好后再开始';$('timerStart').textContent=left===0?'重新计时':t?.end?'暂停计时':t?'继续计时':s.timerLabel;$('timerStart').disabled=view<session.frontier;$('next').disabled=view===session.frontier&&left>0;}
$('timerStart').onclick=()=>{sound.play('click');const t=session.timers[view],left=remaining();session.timers[view]=t?.end&&left>0?{left}:{end:Date.now()+(left||session.recipe.steps[view].seconds)*1000};save();updateTimer();};
$('next').onclick=()=>{if(view<session.frontier){view=session.frontier;render();return;}const step=session.recipe.steps[view];if(step.seconds&&remaining()>0)return;if(view===session.recipe.steps.length-1){sound.play('finish');session.finished=true;save();$('finishText').textContent=`${session.recipe.name} · 约 ${session.config.target}ml`;$('resume').hidden=true;show('finish');return;}sound.play('step');feedback();session.frontier++;view=session.frontier;save();render();};
$('back').onclick=()=>{if(view>0){view--;render();}};$('replay').onclick=()=>{sound.action(session.recipe.steps[view].action);animStart=performance.now();draw(0);};$('resume').onclick=()=>{view=session.frontier;show('ritual');render();};$('choose').onclick=()=>{$('resume').hidden=!session||session.finished;show('welcome');};$('another').onclick=()=>show('welcome');
function draw(t){if(!session)return;lastDraw=t;const steps=session.recipe.steps;$('scene').innerHTML=scene(steps[view],t,session.config,cupState(steps,view,session.config));}
function frame(now){if(!$('ritual').hidden&&session&&now-lastFrame>65){const t=reduced?1:Math.min((now-animStart)/6500,1);if(t!==lastDraw)draw(t);lastFrame=now;}requestAnimationFrame(frame);}show('welcome');requestAnimationFrame(frame);setInterval(()=>{if(session&&!session.finished){for(const t of Object.values(session.timers)){if(t.end&&Date.now()>=t.end&&!t.notified){t.notified=true;sound.play('timer');save();}}}if(!$('ritual').hidden)updateTimer();},250);
